content.solution_code:
class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  activate() {
    return `${this.name} spell is generic activating using ${this.manaCost} mana.`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    this.damage = damage;
  }

  activate() {
    return `${this.name} spell explodes for ${this.damage} damage using ${this.manaCost} mana!`;
  }
}

